def poin_momentum(w1, satuan):
    """Skor momentum: perubahan sepekan dibagi satuan, dibatasi -2..+2."""
    if w1 is None:
        return 0.0
    return clamp(w1 / satuan, -2.0, 2.0)


def poin_tren(m):
    """+0,5 bila harga di atas MA20 yang menanjak; -0,5 bila di bawah MA20 yang menurun; selain itu 0."""
    if not m or m.get("ma20") is None:
        return 0.0
    atas = m["terakhir"] > m["ma20"]
    if atas and m["ma20_naik"]:
        return 0.5
    if (not atas) and (not m["ma20_naik"]):
        return -0.5
    return 0.0


def skor_faktor(m, satuan, tanda):
    """Skor faktor = (momentum + tren) x tanda, dibatasi -2..+2. tanda = -1 untuk faktor berbanding terbalik (DXY, USD/IDR)."""
    return clamp((poin_momentum(m.get("w1") if m else None, satuan) + poin_tren(m)) * tanda, -2.0, 2.0)


def proyeksi_rentang(dasar, sigma_w, skor, lebar=LEBAR, koreksi=0.0, lebar_luar=None, geser=GESER_SKOR):
    """Pusat = dasar x (1 + skor x geser x sigma_w + koreksi); rentang inti = pusat +/- lebar x sigma_w; rentang lebar =
    pusat +/- lebar_luar x sigma_w. Sejak v2.0 geser = 0, jadi titik tengah sama dengan penutupan Jumat."""
    pusat_pct = skor * geser * sigma_w + koreksi
    out = {"pusat_pct": pusat_pct, "pusat": dasar * (1 + pusat_pct / 100.0),
           "bawah": dasar * (1 + (pusat_pct - lebar * sigma_w) / 100.0),
           "atas": dasar * (1 + (pusat_pct + lebar * sigma_w) / 100.0)}
    if lebar_luar:
        out["bawah_lebar"] = dasar * (1 + (pusat_pct - lebar_luar * sigma_w) / 100.0)
        out["atas_lebar"] = dasar * (1 + (pusat_pct + lebar_luar * sigma_w) / 100.0)
    return out


def bias_dari_skor(s):
    if s >= 0.75:
        return "Menguat", "naik"
    if s >= 0.25:
        return "Cenderung menguat", "naik"
    if s > -0.25:
        return "Mendatar", "datar"
    if s > -0.75:
        return "Cenderung melemah", "turun"
