def sigma_mingguan(closes):
    if len(closes) < 22:
        return 3.0
    rets = [math.log(closes[i] / closes[i - 1]) for i in range(len(closes) - 20, len(closes))]
    return clamp(statistics.stdev(rets) * math.sqrt(5) * 100.0, 1.5, 6.0)


def fibonacci(rows):
    """Level retracement Fibonacci bila tren besar sedang berbalik arah.

    Pembalikan naik: titik terendah terjadi dalam 60 sesi terakhir setelah penurunan >= 10% dari puncak 120 sesi
    sebelumnya, harga sudah naik >= 4% dari titik itu dan berada di atas MA20. Pembalikan turun kebalikannya."""
    kosong = {"aktif": False, "arah": "", "level": []}
    rr = [x for x in rows if x[4] is not None][-260:]
    if len(rr) < 80:
        return kosong
    c = [x[4] for x in rr]
    ma20, last, n = sma(c, 20), c[-1], len(rr)
    awal = n - 60
    i_lo = min(range(awal, n), key=lambda i: rr[i][3])
    i_hi = max(range(awal, n), key=lambda i: rr[i][2])
    calon = []
    seb = rr[max(0, i_lo - 120):i_lo]
    if seb:
        j = max(range(len(seb)), key=lambda i: seb[i][2])
        hi, lo = seb[j][2], rr[i_lo][3]
        if (hi - lo) / hi >= 0.10 and last >= lo * 1.04 and last > ma20:
            calon.append((i_lo, "naik", hi, seb[j][0], lo, rr[i_lo][0]))
    seb = rr[max(0, i_hi - 120):i_hi]
    if seb:
        j = min(range(len(seb)), key=lambda i: seb[i][3])
        lo, hi = seb[j][3], rr[i_hi][2]
        if (hi - lo) / lo >= 0.10 and last <= hi * 0.96 and last < ma20:
            calon.append((i_hi, "turun", hi, rr[i_hi][0], lo, seb[j][0]))
    if not calon:
        return kosong
    _, arah, hi, t_hi, lo, t_lo = max(calon)
    lev = [{"rasio": f, "nilai": round(lo + f / 100.0 * (hi - lo)) if arah == "naik" else round(hi - f / 100.0 * (hi - lo))}
           for f in FIB]
    return {"aktif": True, "arah": arah, "tinggi": round(hi), "tgl_tinggi": t_hi, "rendah": round(lo), "tgl_rendah": t_lo,
            "level": lev}


def pivot_mingguan(lw):
    """Pivot klasik dari tertinggi, terendah, dan penutupan pekan lalu."""
    if not lw:
        return {}
    h, l, c = max(x[2] for x in lw), min(x[3] for x in lw), lw[-1][4]
    p = (h + l + c) / 3.0
    return {"P": p, "R1": 2 * p - l, "S1": 2 * p - h, "R2": p + (h - l), "S2": p - (h - l)}


def kalibrasi():
    """Belajar dari pekan-pekan yang sudah selesai (data/history.json).

    - Bobot faktor diperbaiki setiap pekan: dikali 0,6..1,4 menurut seberapa sering arah skornya cocok dengan arah
      IHSG. Satu pekan menggeser pengali paling banyak 10%; makin panjang rekam jejak, makin besar pergeserannya.
    - Titik tengah dikoreksi separuh dari rata-rata selisih (aktual - proyeksi) 8 pekan terakhir (mulai 4 pekan).
    - Lebar rentang dilebarkan 15% bila cakupan rentang inti 12 pekan terakhir < 40%, disempitkan 10% bila > 80%
      (mulai 6 pekan; v1.0 memakai batas 55% dan 85%). Koreksi titik tengah dihitung tetapi tidak dipakai sejak v2.0."""
    hist = [h for h in (load(P("data", "history.json"), []) or []) if h.get("pct") is not None]
    dasar = {f["id"]: f["bobot"] for f in FAKTOR}
    out = {"n": len(hist), "bobot": dict(dasar), "koreksi_pusat": 0.0, "lebar_faktor": 1.0, "catatan": [], "faktor": []}
    kali = {}
    for f in FAKTOR:
        cocok = total = 0
        for h in hist:
            fx = next((x for x in h.get("faktor") or [] if x["id"] == f["id"]), None)
            if not fx or abs(fx["skor"]) < 0.25 or abs(h["pct"]) < 0.1:
                continue
            total += 1
            cocok += (fx["skor"] > 0) == (h["pct"] > 0)
        rate = cocok / float(total) if total else None
        m = 1.0
        if total >= 1:
            m = clamp(1.0 + (rate - 0.5) * 2 * 0.8 * min(total, 8) / 8.0, 0.6, 1.4)
        kali[f["id"]] = m
        out["faktor"].append({"id": f["id"], "faktor": f["nama"], "cocok": cocok, "total": total,
                              "akurasi": r(rate * 100, 0) if rate is not None else None, "pengali": r(m, 2)})
    jumlah = sum(dasar[k] * kali[k] for k in dasar)
    out["bobot"] = {k: r(dasar[k] * kali[k] * 100.0 / jumlah, 1) for k in dasar}
    for x in out["faktor"]:
        x["bobot_dasar"], x["bobot"] = dasar[x["id"]], out["bobot"][x["id"]]
    if not hist:
        out["catatan"].append("Belum ada pekan yang selesai, jadi bobot masih memakai nilai dasar.")
        return out
    if not any(x.get("id") == "tren" for x in hist[-1].get("faktor") or []):
        out["catatan"].append("Model v2.0 berlaku mulai pekan 23 Nov 2026 berdasarkan uji ulang 10 tahun: faktor bursa Asia diganti "
                              "tren lintas pasar, bobot DXY kembali 15%, USD/IDR dipantau tanpa bobot, titik tengah tidak lagi digeser "
                              "skor, dan ada rentang lebar. Bobot faktor baru mulai dikoreksi setelah ada pekan selesai yang memakainya.")
    ubah = [x for x in out["faktor"] if x["bobot_dasar"] and abs(x["bobot"] - x["bobot_dasar"]) >= 0.3]
    if ubah:
        out["catatan"].append("Bobot diperbaiki dari rekam jejak %d pekan: " % len(hist) + "; ".join(
            "%s %s%% menjadi %s%% (arah cocok %d dari %d pekan)" % (x["faktor"], idn(x["bobot_dasar"]), idn(x["bobot"], 1),
                                                                   x["cocok"], x["total"]) for x in ubah) + ".")
    else:
        out["catatan"].append("Rekam jejak %d pekan belum menuntut perubahan bobot." % len(hist))
    if len(hist) < 4:
        out["catatan"].append("Titik tengah dan lebar rentang baru dikoreksi setelah empat pekan selesai.")
        return out
    akhir = hist[-8:]
    selisih = sum(h["pct"] - (h.get("pusat_pct") or 0.0) for h in akhir) / len(akhir)
    out["koreksi_pusat"] = r(clamp(selisih * 0.5, -1.5, 1.5), 2)
    if abs(out["koreksi_pusat"]) >= 0.05:
        out["catatan"].append("Realisasi %d pekan terakhir rata-rata %s%% dari titik tengah; koreksi titik tengah tidak dipakai "
                              "sejak v2.0 karena uji 10 tahun menunjukkan geseran justru menambah galat." % (len(akhir), idn(selisih, 2, True)))
    if len(hist) >= 6:
        cak = len([h for h in hist[-12:] if h.get("dalam_rentang") == "ya"]) / float(len(hist[-12:]))
        if cak < 0.40:
            out["lebar_faktor"] = 1.15
            out["catatan"].append("Rentang dilebarkan 15%%: hanya %s%% pekan terakhir yang ditutup di dalam rentang inti." % idn(cak * 100))
        elif cak > 0.80:
            out["lebar_faktor"] = 0.9
            out["catatan"].append("Rentang disempitkan 10%%: %s%% pekan terakhir ditutup di dalam rentang inti." % idn(cak * 100))
    if not out["catatan"]:
        out["catatan"].append("Rekam jejak %d pekan belum menuntut penyesuaian." % len(hist))
    return out


def hitung_alokasi(profil, skor, sig, prev=None):
    """Porsi portofolio model (persen, total 100) untuk satu profil.

    Saham    = acuan + skor x k (dibatasi +/- batas), dikurangi `vol` poin bila sigma mingguan IHSG > 4%.
    Obl. pjg = acuan - 5 bila suku bunga naik (BI menaikkan bunga atau UST 10 tahun naik > 20 bps sebulan), +5 bila turun.
    Alternatif = emas + kripto + waran: emas -1/+1 menurut posisi emas terhadap MA20, kripto -1/+1 menurut faktor
                 Bitcoin, waran hanya bila bias menguat (skor >= 0,25).
    Porsi yang dilepas (atau ditambah) dibagi rata ke kas dan obligasi pendek.
    Bila ada komposisi pekan lalu, tiap kelas bergeser paling banyak 10 poin."""
    p = PROFIL[profil]
    a = dict(p["acuan"])
    pemicu = []
    d_skor = int(round(clamp(skor * p["k"], -p["batas"], p["batas"])))
    saham = a["saham"] + d_skor
    if d_skor:
        pemicu.append("Skor %s → saham %s" % (idn(skor, 2, True), idn(d_skor, 0, True)))
    if (sig.get("sigma") or 0) > 4.0:
        saham -= p["vol"]
        pemicu.append("Volatilitas tinggi (σ %s%%) → saham −%d" % (idn(sig["sigma"], 1), p["vol"]))
    naik = sig.get("bi_arah") == "naik" or (sig.get("ust_bps") or 0) > 20
    turun = sig.get("bi_arah") == "turun" or (sig.get("ust_bps") or 0) < -20
    panjang = a["panjang"] + (-5 if naik and not turun else 5 if turun and not naik else 0)
    if panjang < a["panjang"]:
        pemicu.append("Suku bunga naik (%s) → obligasi panjang −5" % (
            "BI menaikkan bunga" if sig.get("bi_arah") == "naik" else "UST 10 tahun %s bps sebulan" % idn(sig.get("ust_bps"), 0, True)))
    elif panjang > a["panjang"]:
        pemicu.append("Suku bunga turun → obligasi panjang +5")
    r = dict(p["rinci"])
    ev = sig.get("emas_vs_ma20")
    if ev is not None and ev < 0 and r["emas"] > 0:
        r["emas"] -= 1
        pemicu.append("Emas di bawah MA20 → emas −1")
    elif ev is not None and ev > 0 and sig.get("emas_naik"):
        r["emas"] += 1
        pemicu.append("Emas dalam tren naik → emas +1")
    if sig.get("btc_skor", 0) <= -1 and r["kripto"] > 0:
        r["kripto"] -= 1
        pemicu.append("Bitcoin melemah → kripto −1")
    elif sig.get("btc_skor", 0) >= 1:
        r["kripto"] += 1
        pemicu.append("Bitcoin menguat → kripto +1")
    if skor < 0.25 and r["waran"]:
        pemicu.append("Bias belum menguat → waran 0")
        r["waran"] = 0
    alts = sum(r.values())
    lepas = (a["saham"] - saham) + (a["panjang"] - panjang) + (a["alts"] - alts)
    kas = a["kas"] + int(math.ceil(lepas / 2.0))
    pendek = a["pendek"] + (lepas - int(math.ceil(lepas / 2.0)))
    if kas < 2:
        saham -= 2 - kas
        kas = 2
    if pendek < 5:
        saham -= 5 - pendek
        pendek = 5
    hasil = {"kas": kas, "pendek": pendek, "panjang": panjang, "saham": saham, "alts": alts}
    if prev:
        for k, _ in KELAS:
            if k in prev:
                hasil[k] = int(clamp(hasil[k], prev[k] - GESER_MAKS, prev[k] + GESER_MAKS))
        sisa = 100 - sum(hasil.values())
        hasil["kas"] += sisa
        if hasil["kas"] < 2:
            hasil["pendek"] -= 2 - hasil["kas"]
            hasil["kas"] = 2
    return {"porsi": hasil, "rinci": r, "pemicu": pemicu}


def tren_lintas(ser, asof, ref=None):
    """Faktor v2.0: penguatan atau pelemahan tren di bursa Asia, AS, dan Eropa.

    Diukur dari dua hal: perubahan porsi bursa yang ditutup di atas MA20, dan perubahan RSI 14 rata-rata.
    Tanpa `ref`, perubahan diukur 5 sesi ke belakang dari `asof` (proyeksi awal pekan); dengan `ref`, sejak penutupan
    terakhir <= ref (cek harian: gerak sejak penutupan Jumat).
    Skor = rata-rata (perubahan porsi / 20 poin) dan (perubahan RSI / 5 poin), dibatasi -2..+2."""
    n = a_kini = a_lalu = 0
    rs, drs = [], []
    for k in TREN_PASAR:
        semua = ser.get(k, {}).get("rows", [])
        akhir = bisect.bisect_right(semua, asof, key=lambda x: x[0])
        rows = [x for x in semua[max(0, akhir - 200):akhir] if x[4] is not None]
        if len(rows) < 45:
            continue
        c = [x[4] for x in rows]
        if ref is None:
            j = len(c) - 6
        else:
            j = max([i for i, x in enumerate(rows) if x[0] <= ref] or [-1])
        if j < 25:
            continue
        rsi = rsi_seri(c)
        if rsi[-1] is None or rsi[j] is None:
            continue
        n += 1
        a_kini += c[-1] > sum(c[-20:]) / 20.0
        a_lalu += c[j] > sum(c[j - 19:j + 1]) / 20.0
        rs.append(rsi[-1])
        drs.append(rsi[-1] - rsi[j])
    if n < 6:
        return None
    lebar, lebar_l = 100.0 * a_kini / n, 100.0 * a_lalu / n
    d_rsi = sum(drs) / n
    skor = clamp(((lebar - lebar_l) / TREN_SAT_LEBAR + d_rsi / TREN_SAT_RSI) / 2.0, -2.0, 2.0)
    return {"n": n, "lebar": lebar, "lebar_lalu": lebar_l, "d_lebar": lebar - lebar_l, "rsi": sum(rs) / n,
            "d_rsi": d_rsi, "skor": skor}
